// ricerca
var sBox=document.getElementById('search'),q=document.getElementById('q'),res=document.getElementById('res');
function norm(s){return s.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/’/g,"'")}
function esc(s){return s.replace(/[&<>"]/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]})}
function doSearch(){
  var v=norm(q.value.trim());if(v.length<2){res.innerHTML='';return}
  var hits=IDX.map(function(x){var t=norm(x.x),i=t.indexOf(v);if(i<0)return null;
    return{u:x.u,t:x.t,s:(norm(x.t).indexOf(v)>-1?100:0)+(t.split(v).length-1),n:x.x.substr(Math.max(0,i-50),140)}})
    .filter(Boolean).sort(function(a,b){return b.s-a.s});
  res.innerHTML=hits.length?hits.map(function(h){return '<a href="'+h.u+'"><b>'+esc(h.t)+'</b><span>…'+esc(h.n)+'…</span></a>'}).join('')
    :'<div class="empty">Non abbiamo trovato risultati per questa ricerca. Prova con un altro termine oppure <a href="contatti.html">contattaci</a>.</div>';
}
function closeSearch(){sBox.classList.remove('open')}
document.getElementById('openSearch').onclick=function(){sBox.classList.add('open');q.value='';res.innerHTML='';setTimeout(function(){q.focus()},30)};
document.getElementById('closeSearch').onclick=closeSearch;
sBox.addEventListener('click',function(e){if(e.target===sBox)closeSearch()});
q.addEventListener('input',doSearch);
document.addEventListener('keydown',function(e){if(e.key==='Escape'){closeSearch();closeMenu()}});

