// consenso cookie + Google Analytics (attivo solo se è impostato l'ID)
(function(){
  var c=document.getElementById('cookie');if(!c)return;
  var id=c.dataset.ga,k='wlw-consent',v=null;
  function get(){try{return localStorage.getItem(k)}catch(e){return null}}
  function set(x){try{localStorage.setItem(k,x)}catch(e){}}
  function ga(){if(!id||window.__ga)return;window.__ga=1;var s=document.createElement('script');s.async=true;s.src='https://www.googletagmanager.com/gtag/js?id='+id;document.head.appendChild(s);
    window.dataLayer=window.dataLayer||[];window.gtag=function(){dataLayer.push(arguments)};gtag('js',new Date());gtag('config',id,{anonymize_ip:true})}
  v=get();if(v==='yes')ga();else if(v!=='no')c.hidden=false;
  document.getElementById('ckYes').onclick=function(){set('yes');c.hidden=true;ga()};
  document.getElementById('ckNo').onclick=function(){set('no');c.hidden=true};
  var pr=document.getElementById('cookiePrefs');if(pr)pr.addEventListener('click',function(e){e.preventDefault();c.hidden=false});
})();
